"""Optional NASA C-MAPSS RUL methodology validation. C-MAPSS is turbofan data, not MALE-UAV piston-engine validation."""
from pathlib import Path
import argparse,json,joblib,pandas as pd
from sklearn.ensemble import RandomForestRegressor
from sklearn.metrics import mean_absolute_error,mean_squared_error
p=argparse.ArgumentParser();p.add_argument("--cmapss-dir",required=True);p.add_argument("--subset",default="FD001");p.add_argument("--rul-cap",type=float,default=125.0);a=p.parse_args();ROOT=Path(__file__).resolve().parents[1];D=Path(a.cmapss_dir).expanduser().resolve();O=ROOT/"models";O.mkdir(exist_ok=True);cols=["unit","cycle"]+[f"setting_{i}" for i in range(1,4)]+[f"sensor_{i}" for i in range(1,22)];tr=pd.read_csv(D/f"train_{a.subset}.txt",sep=r"\s+",header=None,names=cols);te=pd.read_csv(D/f"test_{a.subset}.txt",sep=r"\s+",header=None,names=cols);truth=pd.read_csv(D/f"RUL_{a.subset}.txt",sep=r"\s+",header=None,names=["extra_rul"]);tr["RUL"]=(tr.groupby("unit")["cycle"].transform("max")-tr["cycle"]).clip(upper=a.rul_cap);cand=cols[2:];std=tr[cand].std();features=["cycle"]+[x for x in cand if float(std[x])>1e-8];m=RandomForestRegressor(n_estimators=220,max_depth=22,min_samples_leaf=2,random_state=42,n_jobs=-1);m.fit(tr[features],tr.RUL);last=te.sort_values(["unit","cycle"]).groupby("unit").tail(1).sort_values("unit");last["true_RUL"]=truth.extra_rul.to_numpy()[:len(last)];pred=m.predict(last[features]);metrics={"subset":a.subset,"mae_cycles":float(mean_absolute_error(last.true_RUL,pred)),"rmse_cycles":float(mean_squared_error(last.true_RUL,pred)**.5),"rul_cap_cycles":a.rul_cap,"features":features,"domain_note":"NASA C-MAPSS is turbofan data. These metrics validate an RUL methodology, not MALE-UAV aero-piston-engine RUL accuracy."};joblib.dump({"model":m,"features":features,"subset":a.subset,"domain":"NASA C-MAPSS turbofan methodology validation only"},O/"cmapss_rul_method.joblib");(O/"cmapss_rul_metrics.json").write_text(json.dumps(metrics,indent=2));print(json.dumps(metrics,indent=2))
